 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            components.append(cells)
    candidates = []
    for cells in components:
        colors = {grid[r][c] for r,c in cells}
        if len(colors) >= 3:
            r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
            c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
            candidates.append([row[c0:c1+1] for row in grid[r0:r1+1]])
    if len(candidates) != 1:
        raise ValueError(f'Expected one multicolor object, got {len(candidates)}')
    return candidates[0]
